mapper.select:
select T1.PORTFOLIO_ID id, T1.PORTFOLIO_NAME text from PTL_PORTFOLIO T1/**组合表**/ inner join PTL_PORTFOLIO_AUTHORITY T2/**组合权限表**/ on T2.PORTFOLIO_ID = T1.PORTFOLIO_ID and T2.USER_ID = #{loginUserName} /**系统登录用户**/ where 1=1
AND T1.PORTFOLIO_TYPE = #{portfolioType}
AND T1.INVEST_YESORNO = #{investYesOrNo}
AND (T1.PORTFOLIO_ID like concat('%',concat(#{search},'%')) OR T1.PORTFOLIO_NAME like concat('%',concat(#{search},'%')))

select T1.PORTFOLIO_ID id, T1.PORTFOLIO_NAME text from PTL_PORTFOLIO T1/**组合表**/ where 1=1
AND T1.PORTFOLIO_TYPE = #{portfolioType}
AND (T1.PORTFOLIO_ID like concat('%',concat(#{search},'%')) OR T1.PORTFOLIO_NAME like concat('%',concat(#{search},'%')))

select total.TOTLE_TRADE_ID totleTradeId,/**汇总交易编号**/ deal.TRADE_ID tradeId,/**交易编号**/ total.PORTFOLIO_ID portfolioId,/**组合代码**/ ptl1.PORTFOLIO_NAME portfolioName,/**组合名称**/ dealAdd.PORTFOLIO_ID subPortfolioId,/**子组合代码**/ ptl2.PORTFOLIO_NAME subPortfolioName,/**子组合名称**/ dis.DIS_PERCENT*100 disPercent,/**继承比例%**/ ptl2.REMARK remark,/**备注**/ to_char(total.SETTLE_DATE,'yyyy-mm-dd') settleDate,/**调配日期**/ deal.CCY ccy,/**币种**/
case when deal.PS='C4' then deal.TRADE_AMT*(-1) else deal.TRADE_AMT end tradeAmt,/**调配金额**/ deal.REMARK deployrRemark /**调配备注**/, ptl1.PARENT_PORTFOLIO_ID parentPortfolioId from TRD_FIN_PRODUCT_DEAL_TOTAL total/**金融产品交易汇总**/ left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL paTotal /**金融产品交易汇总扩展**/ on total.TOTLE_TRADE_ID = paTotal.TOTLE_TRADE_ID left join TRD_PRODUCT_DEAL deal/**金融产品交易**/ on deal.TOTLE_TRADE_ID = total.TOTLE_TRADE_ID left join TRD_PRODUCT_DEAL_ADD dealAdd /**金融产品交易附属**/ on deal.TRADE_ID = dealAdd.TRADE_ID left join PTL_PORTFOLIO_DIS dis /**组合资金分配比例**/ on dis.PORTFOLIO_ID = dealAdd.PORTFOLIO_ID left join PTL_PORTFOLIO ptl1 /**组合1**/ on ptl1.PORTFOLIO_ID = total.PORTFOLIO_ID left join PTL_PORTFOLIO ptl2 /**组合2**/ on ptl2.PORTFOLIO_ID = dealAdd.PORTFOLIO_ID where total.FINPROD_TYPE2 = #{finprodType2} /**数据字典缓存.业务类型.理财产品**/ and paTotal.PA_BUSS_TYPE = #{paBussType} /**数据字典缓存.平安业务类型.产品交易资金分配**/ and total.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) /**系统当前登陆者**/
and total.PORTFOLIO_ID in
#{item}
and total.SETTLE_DATE >= to_date(#{settleDateBegin},'yyyy-mm-dd')
and total.SETTLE_DATE <= to_date(#{settleDateEnd},'yyyy-mm-dd')
and NVL(total.IS_CANCEL,' ') <> #{isCancle}
and dealAdd.PORTFOLIO_ID in
#{item}
order by total.TRADE_DATE,total.PORTFOLIO_ID,total.TOTLE_TRADE_ID desc

select FIN_PRODUCT.FINPROD_ABBR, FIN_PRODUCT.FINPROD_MARKET_ID, FIN_CASH_INFO.CASH_ID CASH_ID_STR, MST_FEEINFO.FEE_NAME, MST_FEEINFO.FEE_TYPE, PRD_LAYER_PARAM.PROD_STYLE FROM FIN_CASH_INFO, MST_FEEINFO,FIN_PRODUCT LEFT JOIN PRD_LAYER_PARAM ON FIN_PRODUCT.FINPROD_ID = PRD_LAYER_PARAM.FINPROD_ID where FIN_PRODUCT.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} AND FIN_PRODUCT.FINPROD_TYPE = #{finprodType2,jdbcType=VARCHAR} AND FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID AND MST_FEEINFO.CHARGE_TYPE = #{chargeType01,jdbcType=VARCHAR} AND FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR} AND FIN_CASH_INFO.CASH_TYPE_2 IN
#{item,jdbcType=VARCHAR}
AND FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID

select total.TOTLE_TRADE_ID totleTradeId,/**汇总交易编号**/ deal.TRADE_ID tradeId,/**交易编号**/ total.PORTFOLIO_ID portfolioId,/**组合代码**/ ptl1.PORTFOLIO_NAME portfolioName,/**组合名称**/ dealAdd.PORTFOLIO_ID subPortfolioId,/**子组合代码**/ ptl2.PORTFOLIO_NAME subPortfolioName,/**子组合名称**/ dis.DIS_PERCENT*100 disPercent,/**继承比例%**/ ptl2.REMARK remark,/**备注**/ to_char(total.SETTLE_DATE,'yyyy-mm-dd') settleDate,/**调配日期**/ deal.CCY ccy,/**币种**/ case when deal.PS='C4' then deal.TRADE_AMT*(-1) else deal.TRADE_AMT end tradeAmt,/**调配金额**/ deal.REMARK deployrRemark /**调配备注**/ ,A.actualAmt from TRD_FIN_PRODUCT_DEAL_TOTAL total/**金融产品交易汇总**/ left join TRD_PRODUCT_DEAL deal/**金融产品交易**/ on deal.TOTLE_TRADE_ID = total.TOTLE_TRADE_ID left join TRD_PRODUCT_DEAL_ADD dealAdd /**金融产品交易附属**/ on deal.TRADE_ID = dealAdd.TRADE_ID left join PTL_PORTFOLIO_DIS dis /**组合资金分配比例**/ on dis.PORTFOLIO_ID = dealAdd.PORTFOLIO_ID left join PTL_PORTFOLIO ptl1 /**组合1**/ on ptl1.PORTFOLIO_ID = total.PORTFOLIO_ID left join PTL_PORTFOLIO ptl2 /**组合2**/ on ptl2.PORTFOLIO_ID = dealAdd.PORTFOLIO_ID left join ( select NVL(SUM(PF.AMOUNT),0) actualAmt, PF.PORTFOLIO_ID subPortfolioId, PF.CCY ccy from PTL_CASH_POSITION_FLOW PF INNER JOIN PTL_CAPACCT_INFO PC ON PC.PORTFOLIO_ID=PF.PORTFOLIO_ID AND PC.ACCT_NO=PF.ACCT_ID AND PC.ACCT_TYPE='${acctType}' AND PF.CCY=PC.CCY WHERE 1=1 and PF.PORTFOLIO_ID IN (select T1.PORTFOLIO_ID from PTL_PORTFOLIO T1/**组合表**/ where 1=1
AND T1.PARENT_PORTFOLIO_ID = #{parentPortfolioId}
)
AND PF.HODING_TYPE = #{hodingType}
AND PF.CCY = #{ccy}
GROUP BY PF.PORTFOLIO_ID,PF.CCY) A on dealAdd.PORTFOLIO_ID = A.subPortfolioId and deal.CCY = A.ccy
where 1=1
AND total.TOTLE_TRADE_ID = #{totleTradeId}
order by total.TRADE_DATE,total.PORTFOLIO_ID,total.TOTLE_TRADE_ID desc

select total.TOTLE_TRADE_ID totleTradeId,/**汇总交易编号**/ deal.TRADE_ID tradeId,/**交易编号**/ total.PORTFOLIO_ID portfolioId,/**组合代码**/ ptl1.PORTFOLIO_NAME portfolioName,/**组合名称**/ dealAdd.PORTFOLIO_ID subPortfolioId,/**子组合代码**/ ptl2.PORTFOLIO_NAME subPortfolioName,/**子组合名称**/ dis.DIS_PERCENT*100 disPercent,/**继承比例%**/ ptl2.REMARK remark,/**备注**/ to_char(total.SETTLE_DATE,'yyyy-mm-dd') settleDate,/**调配日期**/ deal.CCY ccy,/**币种**/ case when deal.PS='C4' then deal.TRADE_AMT*(-1) else deal.TRADE_AMT end tradeAmt,/**调配金额**/ deal.REMARK deployrRemark /**调配备注**/ ,A.actualAmt from wfl_trd_fin_product_deal_total total/**金融产品交易汇总**/ left join wfl_trd_product_deal deal/**金融产品交易**/ on deal.TOTLE_TRADE_ID = total.TOTLE_TRADE_ID left join wfl_trd_product_deal_add dealAdd /**金融产品交易附属**/ on deal.TRADE_ID = dealAdd.TRADE_ID left join PTL_PORTFOLIO_DIS dis /**组合资金分配比例**/ on dis.PORTFOLIO_ID = dealAdd.PORTFOLIO_ID left join PTL_PORTFOLIO ptl1 /**组合1**/ on ptl1.PORTFOLIO_ID = total.PORTFOLIO_ID left join PTL_PORTFOLIO ptl2 /**组合2**/ on ptl2.PORTFOLIO_ID = dealAdd.PORTFOLIO_ID
left join ( select NVL(SUM(PF.AMOUNT),0) actualAmt, PF.PORTFOLIO_ID subPortfolioId, PF.CCY ccy from PTL_CASH_POSITION_FLOW PF /**设计修改 add by leipeng 20190910**/ INNER JOIN PTL_CAPACCT_INFO PC ON PC.PORTFOLIO_ID=PF.PORTFOLIO_ID AND PC.ACCT_NO=PF.ACCT_ID AND PC.ACCT_TYPE='${acctType}' AND PF.CCY=PC.CCY
WHERE 1=1 and PF.PORTFOLIO_ID IN (select T1.PORTFOLIO_ID from PTL_PORTFOLIO T1/**组合表**/ where 1=1
AND T1.PARENT_PORTFOLIO_ID = #{portfolioId}
)
AND PF.HODING_TYPE = #{hodingType}
AND PF.CCY = #{ccy}
GROUP BY PF.PORTFOLIO_ID,PF.CCY) A on total.PORTFOLIO_ID = A.subPortfolioId and deal.CCY = A.ccy
where 1=1
AND total.TOTLE_TRADE_ID = #{totleTradeId}
order by total.TRADE_DATE,total.PORTFOLIO_ID,total.TOTLE_TRADE_ID desc

select T1.PARENT_PORTFOLIO_ID parentPortfolioId, T1.PORTFOLIO_ID portfolioId, T1.PORTFOLIO_NAME portfolioName, T1.PORTFOLIO_ID subPortfolioId, T1.PORTFOLIO_NAME subPortfolioName, dis.DIS_PERCENT*100 disPercent, T1.REMARK remark, A.actualAmt,A.ccy from PTL_PORTFOLIO T1/**组合表**/ left join PTL_PORTFOLIO_DIS dis /**组合资金分配比例**/ on dis.PORTFOLIO_ID = T1.PORTFOLIO_ID left join ( select NVL(SUM(PF.AMOUNT),0) actualAmt, PF.PORTFOLIO_ID subPortfolioId, PF.CCY ccy from PTL_CASH_POSITION_FLOW PF /**设计修改 add by leipeng 20190910**/ INNER JOIN PTL_CAPACCT_INFO PC ON PC.PORTFOLIO_ID=PF.PORTFOLIO_ID AND PC.ACCT_NO=PF.ACCT_ID AND PC.ACCT_TYPE='${acctType}' AND PF.CCY=PC.CCY
WHERE 1=1 and PF.PORTFOLIO_ID IN (select T1.PORTFOLIO_ID from PTL_PORTFOLIO T1/**组合表**/ where 1=1
AND T1.PARENT_PORTFOLIO_ID = #{portfolioId}
)
AND PF.HODING_TYPE = #{hodingType}
AND PF.CCY = #{ccy}
GROUP BY PF.PORTFOLIO_ID,PF.CCY) A on T1.PORTFOLIO_ID = A.subPortfolioId where 1=1
AND T1.PARENT_PORTFOLIO_ID = #{portfolioId}

		select
		    NVL(SUM(AMOUNT),0) actualAmt,
		    PORTFOLIO_ID subPortfolioId,
		    CCY ccy  
		from 
		PTL_CASH_POSITION_FLOW
		WHERE 1=1 and PORTFOLIO_ID = #{subPortfolioId,jdbcType=VARCHAR}

    		AND HODING_TYPE =  #{hodingType}


    		AND CCY =  #{ccy}

		GROUP BY PORTFOLIO_ID,CCY

select NVL(SUM(PF.AMOUNT),0) avaAmt, PF.PORTFOLIO_ID subPortfolioId, PF.CCY ccy from PTL_CASH_POSITION_FLOW PF /**设计修改 add by leipeng 20190910**/ INNER JOIN PTL_CAPACCT_INFO PC ON PC.PORTFOLIO_ID=PF.PORTFOLIO_ID AND PC.ACCT_NO=PF.ACCT_ID AND PC.ACCT_TYPE='${acctType}' AND PF.CCY=PC.CCY WHERE 1=1 and PF.PORTFOLIO_ID = #{subPortfolioId,jdbcType=VARCHAR}
AND PF.HODING_TYPE = #{hodingType}
AND PF.CCY = #{ccy}
GROUP BY PF.PORTFOLIO_ID,PF.CCY

		select count(pm.WORKFLOW_ID)
    	from SYS_DATA_PROCESS_MARK pm

    		pm.status in ('A','U','P')

    			and pm.PAGE_ID = #{pageId}


            	and pm.BUSINESS_DATA_PK1 = #{businessDataPk1}


				and pm.BUSINESS_DATA_PK2 = #{businessDataPk2}


				and pm.BUSINESS_DATA_PK3 = #{businessDataPk3}


    	order by pm.create_time desc

select T1.PORTFOLIO_ID id, T1.PORTFOLIO_ID || ':' || T1.PORTFOLIO_NAME text from PTL_PORTFOLIO T1/**组合表**/ inner join PTL_PORTFOLIO_AUTHORITY T2/**组合权限表**/ on T2.PORTFOLIO_ID = T1.PORTFOLIO_ID and T2.USER_ID = #{loginUserName} /**系统登录用户**/ where 1=1
AND T1.PORTFOLIO_TYPE = #{portfolioType}
AND T1.INVEST_YESORNO = #{investYesOrNo}
AND (T1.PORTFOLIO_ID like concat('%',concat(#{search},'%')) OR T1.PORTFOLIO_NAME like concat('%',concat(#{search},'%')))
